/* Ask Leo: built-in question bank for the offline version.
   Each entry: id, topic, q (question), alt (other phrasings, | separated), a: ['leo', answer]. */
window.LEO_QA = [

  /* ---------------- Sun ---------------- */
  { id: 'sun-hot', topic: 'Sun', q: 'How hot is the Sun?', alt: 'temperature of the sun|is the sun hot|how warm is the sun|sun temperature|how hot is the son|sun heat', a: ['leo', 'The surface of the Sun is about 5,500 degrees Celsius, which is hotter than any oven on Earth. Deep in the middle it is around 15 million degrees. That heat travels all the way to us and keeps our planet cosy.'] },
  { id: 'sun-what', topic: 'Sun', q: 'What is the Sun?', alt: 'what is the sun made of|is the sun a star|sun made of|what is the son|what the sun is', a: ['leo', 'The Sun is a star, just like the ones you see twinkling at night. It is a giant ball of glowing gas, mostly hydrogen and helium. It only looks bigger and brighter than other stars because it is so much closer to us.'] },
  { id: 'sun-how-works', topic: 'Sun', q: 'How does the Sun shine?', alt: 'why does the sun shine|how does the sun make light|why is the sun bright|how does the sun work|where does sunlight come from', a: ['leo', 'Deep inside the Sun, tiny bits of hydrogen are squeezed together so hard that they join up and make helium. This is called nuclear fusion, and it gives off huge amounts of light and heat. The Sun has been doing this for about 4.6 billion years.'] },
  { id: 'sun-big', topic: 'Sun', q: 'How big is the Sun?', alt: 'size of the sun|is the sun bigger than earth|how many earths fit in the sun|sun size|how big is the son', a: ['leo', 'The Sun is enormous. You could line up about 109 Earths across its middle, and around 1.3 million Earths could fit inside it. If the Sun were as big as a front door, Earth would be about the size of a small coin.'] },
  { id: 'sun-far', topic: 'Sun', q: 'How far away is the Sun?', alt: 'distance to the sun|how far is the sun|how long to get to the sun|sun distance|how far away is the son', a: ['leo', 'The Sun is about 150 million kilometres away. Even light, the fastest thing there is, takes about 8 minutes to get here. A car driving without stopping would need well over 100 years to get there.'] },
  { id: 'sun-burn-out', topic: 'Sun', q: 'Will the Sun burn out?', alt: 'will the sun die|when will the sun go out|will the sun run out|does the sun last forever|sun dying', a: ['leo', 'Not for a very, very long time. Scientists think the Sun has enough fuel for about another 5 billion years. That is so far in the future that it is nothing for anyone to worry about. The Sun will keep shining for us.'] },
  { id: 'sun-look', topic: 'Sun', q: 'Why should I not look at the Sun?', alt: 'can i look at the sun|is it bad to look at the sun|staring at the sun|why cant i look at the sun|looking at sun', a: ['leo', 'The Sun is so bright that its light can hurt your eyes, even if you only look for a short time. Never look straight at it, even with sunglasses. Scientists use special filters to study the Sun safely.'] },
  { id: 'sun-eclipse', topic: 'Sun', q: 'What is a solar eclipse?', alt: 'eclipse|why does the sun go dark|solar eclipse|what is an eclipse|eclips|moon covers the sun', a: ['leo', 'A solar eclipse happens when the Moon passes between the Sun and Earth and blocks the sunlight. The Sun is about 400 times wider than the Moon, but also about 400 times further away, so they look the same size. Only watch an eclipse with special eclipse glasses.'] },
  { id: 'sun-sky-blue', topic: 'Sun', q: 'Why is the sky blue?', alt: 'why the sky is blue|what makes the sky blue|blue sky|why is sky blue|y is the sky blue', a: ['leo', 'Sunlight is made of all the colours of the rainbow mixed together. When it hits the air, the blue light gets bounced around the sky much more than the other colours. So wherever you look, blue light is coming towards your eyes.'] },
  { id: 'sun-sunset', topic: 'Sun', q: 'Why are sunsets orange and red?', alt: 'why is the sunset red|sunset colours|why is the sky orange at night|red sky|why sunsets are pink', a: ['leo', 'At sunset the light has to travel through much more air to reach you. Most of the blue light gets scattered away on the journey, so the reds, oranges and pinks are left. That is why evening skies can look like they are on fire.'] },
  { id: 'sun-move', topic: 'Sun', q: 'Does the Sun move?', alt: 'does the sun go round the earth|why does the sun move across the sky|where does the sun go at night|sun moving', a: ['leo', 'The Sun looks like it moves across the sky, but really it is Earth that is spinning. As we turn, the Sun seems to rise and set. The Sun does travel too, though. It carries all the planets with it around the middle of our galaxy.'] },
  { id: 'sun-colour', topic: 'Sun', q: 'What colour is the Sun?', alt: 'is the sun yellow|sun colour|what color is the sun|is the sun white|sun color', a: ['leo', 'From space, the Sun actually looks white. It gives out every colour of light mixed together. It looks yellow to us because our air scatters some of the blue light away, especially when the Sun is low in the sky.'] },
  { id: 'sun-age', topic: 'Sun', q: 'How old is the Sun?', alt: 'when was the sun made|how old is the son|sun age|when was the sun born', a: ['leo', 'The Sun is about 4.6 billion years old. It formed from a huge spinning cloud of gas and dust, and the planets formed from the leftovers. It is about halfway through its life, like a grown up star in the middle of its story.'] },
  { id: 'sun-aurora', topic: 'Sun', q: 'What are the northern lights?', alt: 'aurora|northern lights|aurora borealis|what makes the northern lights|can i see the northern lights in the uk|norhtern lights', a: ['leo', 'The Sun sends out a stream of tiny charged particles called the solar wind. When they reach Earth, they bump into the air high above the poles and make it glow green, pink and purple. Sometimes you can even see them from the UK on a dark, clear night.'] },

  /* ---------------- Planets ---------------- */
  { id: 'planets-how-many', topic: 'Planets', q: 'How many planets are there?', alt: 'number of planets|how many planets in the solar system|8 planets|how many planits|how many plannets are there', a: ['leo', 'There are eight planets in our Solar System: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune. A fun way to remember them is My Very Easy Method Just Speeds Up Naming. There are also dwarf planets, like Pluto.'] },
  { id: 'planets-order', topic: 'Planets', q: 'What order are the planets in?', alt: 'planets in order|order of the planets|which planet is closest to the sun|list the planets|planet order', a: ['leo', 'Starting nearest the Sun, the order is Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune. The first four are small and rocky. The last four are giant planets made mostly of gas and ice. Pluto is further out still.'] },
  { id: 'planets-biggest', topic: 'Planets', q: 'What is the biggest planet?', alt: 'biggest planet|largest planet|wats the bigest planet|jupiter size|how big is jupiter|biggest plannet', a: ['leo', 'Jupiter is the biggest planet by far. About 11 Earths could line up across it, and around 1,300 Earths could fit inside. All the other planets in the Solar System could squeeze into Jupiter with room to spare.'] },
  { id: 'planets-smallest', topic: 'Planets', q: 'What is the smallest planet?', alt: 'smallest planet|tiniest planet|littlest planet|smalest planet|which planet is smallest', a: ['leo', 'Mercury is the smallest planet. It is only a little bigger than our Moon. Pluto is smaller still, but Pluto is called a dwarf planet, so Mercury wins the prize for the smallest proper planet.'] },
  { id: 'planets-hottest', topic: 'Planets', q: 'What is the hottest planet?', alt: 'hottest planet|which planet is the hottest|is mercury the hottest|hotest planet|warmest planet', a: ['leo', 'Venus is the hottest planet, at about 465 degrees Celsius. That is hot enough to melt lead. Even though Mercury is closer to the Sun, Venus has a thick blanket of clouds that traps the heat, like a car left in the sunshine with the windows shut.'] },
  { id: 'planets-coldest', topic: 'Planets', q: 'What is the coldest planet?', alt: 'coldest planet|which planet is the coldest|freezing planet|coldist planet|iciest planet', a: ['leo', 'Uranus has the coldest air of any planet, dropping to about minus 224 degrees Celsius. Neptune is further away but has a little heat inside it, so it is not quite as chilly. Both are far colder than any freezer.'] },
  { id: 'planets-why-round', topic: 'Planets', q: 'Why are planets round?', alt: 'why are planets ball shaped|why is earth round|why arent planets square|why are planets spheres|round planets', a: ['leo', 'Gravity pulls everything towards the middle of a planet from every side equally. Over a long time, that squeezes a big planet into a ball shape. Small space rocks do not have enough gravity, so they can be lumpy, like potatoes.'] },
  { id: 'planets-made', topic: 'Planets', q: 'How were the planets made?', alt: 'how did the planets form|where did the planets come from|how are planets made|how was earth made|planets made', a: ['leo', 'About 4.6 billion years ago, a spinning disc of gas and dust surrounded the young Sun. Little bits stuck together, like snowballs rolling in snow, and grew bigger and bigger. Over millions of years they became the planets.'] },
  { id: 'planets-dwarf', topic: 'Planets', q: 'What is a dwarf planet?', alt: 'dwarf planet|what are dwarf planets|dwarf planets list|dworf planet|how many dwarf planets', a: ['leo', 'A dwarf planet is round like a planet but has not cleared other objects out of its path around the Sun. There are five official ones: Pluto, Ceres, Eris, Haumea and Makemake. Scientists think there could be many more waiting to be found.'] },
  { id: 'planets-rings', topic: 'Planets', q: 'Which planets have rings?', alt: 'planets with rings|does jupiter have rings|rings on planets|which planets have rings|ringed planets', a: ['leo', 'All four giant planets have rings: Jupiter, Saturn, Uranus and Neptune. Saturn has the biggest and brightest rings by far. The others have thin, dark rings that are very hard to see, so scientists only found them using telescopes and spacecraft.'] },
  { id: 'planets-most-moons', topic: 'Planets', q: 'Which planet has the most moons?', alt: 'most moons|how many moons does saturn have|planet with most moons|how many moons does jupiter have|moons count', a: ['leo', 'Saturn has the most moons, with around 270 found so far. Jupiter is next with nearly 100. Many of them are tiny, only a few kilometres across, and scientists keep discovering new ones.'] },
  { id: 'planets-see', topic: 'Planets', q: 'Can I see planets from my garden?', alt: 'can you see planets without a telescope|see planets at night|which planets can i see|is that star a planet|spot a planet', a: ['leo', 'Yes. Mercury, Venus, Mars, Jupiter and Saturn can all be seen with just your eyes. They look like bright stars, but they usually do not twinkle as much. Venus is the brightest and is often called the evening star.'] },
  { id: 'planets-other-stars', topic: 'Planets', q: 'Are there planets around other stars?', alt: 'exoplanets|what is an exoplanet|planets outside the solar system|other solar systems|exoplanet', a: ['leo', 'Yes. Planets around other stars are called exoplanets, and scientists have found more than 6,000 of them. Some are giant and puffy, some are rocky like Earth, and some orbit two suns at once. Most stars probably have planets.'] },
  { id: 'mercury-facts', topic: 'Planets', q: 'What is Mercury like?', alt: 'mercury|tell me about mercury|mercury facts|mercury planet|merkury', a: ['leo', 'Mercury is the smallest planet and the closest to the Sun. It is grey, rocky and covered in craters, a bit like our Moon. It whizzes around the Sun in just 88 days, so a year there is shorter than three of our months.'] },
  { id: 'mercury-temp', topic: 'Planets', q: 'Is Mercury hot or cold?', alt: 'how hot is mercury|mercury temperature|is mercury cold|mercury hot and cold', a: ['leo', 'Both. In the daytime Mercury heats up to about 430 degrees Celsius. At night it drops to about minus 180 degrees, because it has almost no air to hold the heat in. It is like going from a pizza oven to a giant freezer.'] },
  { id: 'mercury-day', topic: 'Planets', q: 'How long is a day on Mercury?', alt: 'mercury day|how long is a year on mercury|day on mercury|mercury day length', a: ['leo', 'Mercury spins very slowly. From one sunrise to the next takes about 176 Earth days. But it only takes 88 Earth days to go around the Sun, so one day on Mercury lasts as long as two of its years.'] },
  { id: 'venus-facts', topic: 'Planets', q: 'What is Venus like?', alt: 'venus|tell me about venus|venus facts|venus planet|venis', a: ['leo', 'Venus is almost the same size as Earth, but it is very different. It is covered in thick yellow clouds, the air is very heavy, and it is the hottest planet. It is also the brightest planet in our night sky.'] },
  { id: 'venus-day', topic: 'Planets', q: 'How long is a day on Venus?', alt: 'venus day|day on venus|venus spins backwards|year on venus|venus day longer than year', a: ['leo', 'Venus takes 243 Earth days to spin round once, but only 225 Earth days to go around the Sun. So a day on Venus is longer than its year. It also spins backwards, so there the Sun would rise in the west.'] },
  { id: 'venus-stand', topic: 'Planets', q: 'Could I stand on Venus?', alt: 'can you land on venus|could i live on venus|walk on venus|visit venus', a: ['leo', 'Venus has a solid surface, but it is far too hot and the air presses down very hard, like being deep under the sea. Robot landers called Venera reached it long ago and sent back pictures before the heat stopped them. It is a planet best explored by robots.'] },
  { id: 'earth-planet-facts', topic: 'Planets', q: 'What makes Earth special?', alt: 'why is earth special|earth facts|what is special about earth|why do we live on earth|earth planet', a: ['leo', 'Earth is the only planet we know of with life. It has liquid water, air we can breathe, and it is just the right distance from the Sun, not too hot and not too cold. Scientists sometimes call this the Goldilocks zone.'] },
  { id: 'jupiter-facts', topic: 'Planets', q: 'What is Jupiter like?', alt: 'jupiter|tell me about jupiter|jupiter facts|jupitor|what is jupiter made of', a: ['leo', 'Jupiter is a gas giant, made mostly of hydrogen and helium. It has colourful stripes of clouds and huge storms. It spins very fast, so a day there is less than 10 hours, but a year takes about 12 Earth years.'] },
  { id: 'jupiter-red-spot', topic: 'Planets', q: 'What is the Great Red Spot?', alt: 'great red spot|red spot on jupiter|jupiter storm|big red spot|jupiter red dot', a: ['leo', 'The Great Red Spot is a giant storm on Jupiter that is wider than the whole Earth. People have been watching it for more than 150 years, and maybe longer. It has been slowly shrinking, but it is still the biggest storm in the Solar System.'] },
  { id: 'jupiter-stand', topic: 'Planets', q: 'Could I stand on Jupiter?', alt: 'can you land on jupiter|does jupiter have ground|walk on jupiter|stand on a gas giant|could i live on jupiter', a: ['leo', 'No, because Jupiter has no solid ground to stand on. If you tried to land, you would just sink deeper and deeper through clouds that get thicker and hotter. It is a bit like trying to stand on a cloud.'] },
  { id: 'jupiter-moons', topic: 'Planets', q: 'What are the moons of Jupiter?', alt: 'jupiter moons|io|ganymede|callisto|europa moon|biggest moon', a: ['leo', 'Jupiter has nearly 100 moons. The four biggest are Io, Europa, Ganymede and Callisto. Io has hundreds of volcanoes, Europa has a hidden ocean, and Ganymede is the biggest moon in the Solar System, even bigger than Mercury.'] },
  { id: 'saturn-facts', topic: 'Planets', q: 'What is Saturn like?', alt: 'saturn|tell me about saturn|saturn facts|saturne|planet with rings', a: ['leo', 'Saturn is the second biggest planet and is famous for its beautiful rings. Like Jupiter, it is a giant ball of gas. A day there is about 10 and a half hours, but a year lasts about 29 Earth years.'] },
  { id: 'saturn-rings', topic: 'Planets', q: 'What are the rings of Saturn made of?', alt: 'saturn rings|what are saturns rings|rings made of|why does saturn have rings|saturn ring', a: ['leo', 'The rings of Saturn are made of billions of pieces of ice and rock. Some are as small as grains of sand and some are as big as a house. The rings are incredibly wide, but in most places they are thinner than a tall building is high.'] },
  { id: 'saturn-float', topic: 'Planets', q: 'Would Saturn float in water?', alt: 'saturn float|can saturn float|saturn in a bath|saturn floating', a: ['leo', 'Saturn is so light for its size that it is less dense than water. So if you could find a bathtub big enough, scientists say it would float. Of course, no bath that big exists, but it is a fun way to imagine it.'] },
  { id: 'saturn-titan', topic: 'Planets', q: 'What is Titan?', alt: 'titan|saturn moon titan|titan moon|biggest moon of saturn|tightan', a: ['leo', 'Titan is the biggest moon of Saturn. It has thick orange air and lakes and rivers, but they are filled with liquid methane, not water. NASA is building a flying robot called Dragonfly to explore it in the 2030s.'] },
  { id: 'uranus-facts', topic: 'Planets', q: 'What is Uranus like?', alt: 'uranus|tell me about uranus|uranus facts|urenus|yuranus', a: ['leo', 'Uranus is an ice giant with a pale blue green colour. Its strangest trick is that it spins on its side, so it rolls around the Sun like a ball. A year there lasts 84 Earth years and it has about 28 moons.'] },
  { id: 'uranus-side', topic: 'Planets', q: 'Why does Uranus spin on its side?', alt: 'uranus tilted|uranus sideways|why is uranus on its side|uranus spinning', a: ['leo', 'Scientists think something very big crashed into Uranus long ago and knocked it over. Because it is tipped on its side, each pole gets about 42 years of daylight and then 42 years of darkness. That is a very long night.'] },
  { id: 'neptune-facts', topic: 'Planets', q: 'What is Neptune like?', alt: 'neptune|tell me about neptune|neptune facts|neptoon|furthest planet', a: ['leo', 'Neptune is the furthest planet from the Sun. It is a deep blue ice giant with the fastest winds in the Solar System, up to about 2,000 kilometres an hour. One year on Neptune lasts about 165 Earth years.'] },
  { id: 'neptune-found', topic: 'Planets', q: 'How was Neptune found?', alt: 'who discovered neptune|neptune discovery|when was neptune found', a: ['leo', 'Neptune was found in 1846 using maths. Astronomers noticed Uranus was being tugged by something they could not see. They worked out where the hidden planet should be, pointed a telescope there, and found Neptune.'] },
  { id: 'planets-live', topic: 'Planets', q: 'Could we live on another planet?', alt: 'can we live on another planet|could people live on other planets|move to another planet|live on a planet|new home planet', a: ['leo', 'No other planet is as comfy as Earth. Most are too hot, too cold, or have no air to breathe. Mars is the most likely place people might visit and build bases one day, but they would need special homes and spacesuits.'] },
  { id: 'planets-gravity', topic: 'Planets', q: 'Would I weigh the same on other planets?', alt: 'weight on other planets|how much would i weigh on mars|gravity on other planets|jump on other planets|weigh on jupiter', a: ['leo', 'No. On Mars you would feel only about a third as heavy, so you could jump much higher. On the Moon you would feel about a sixth as heavy. On Jupiter you would feel more than twice as heavy, like carrying a friend on your back.'] },
  { id: 'planets-ceres', topic: 'Planets', q: 'What is Ceres?', alt: 'ceres|ceres dwarf planet|series planet|biggest asteroid', a: ['leo', 'Ceres is a dwarf planet in the asteroid belt between Mars and Jupiter. It is the biggest object in the belt. A spacecraft called Dawn visited it and found bright white spots, which turned out to be salty patches.'] },
  { id: 'planets-planet-nine', topic: 'Planets', q: 'Is there a Planet Nine?', alt: 'planet nine|planet 9|planet x|is there a ninth planet|hidden planet', a: ['leo', 'Some scientists think there might be a hidden planet far beyond Neptune, because some small icy objects out there move in a strange way. Nobody has found it yet. Maybe one day someone will spot it with a telescope.'] },

  /* ---------------- Moon ---------------- */
  { id: 'moon-what', topic: 'Moon', q: 'What is the Moon?', alt: 'what is the moon made of|moon made of|is the moon cheese|what is moon|moon rock', a: ['leo', 'The Moon is a big ball of rock that travels around Earth. It is not made of cheese, sadly. It is grey and dusty, and covered in craters made by space rocks crashing into it long ago.'] },
  { id: 'moon-phases', topic: 'Moon', q: 'Why does the Moon change shape?', alt: 'moon phases|why does the moon change|half moon|crescent moon|full moon|new moon|phases of the moon', a: ['leo', 'The Moon does not really change shape. The Sun always lights up half of it, and as the Moon travels around Earth we see different amounts of that sunny half. It goes from new moon to full moon and back again in about 29 and a half days.'] },
  { id: 'moon-daytime', topic: 'Moon', q: 'Why can I see the Moon in the daytime?', alt: 'moon in the day|why is the moon out in the day|daytime moon|moon during the day', a: ['leo', 'The Moon is bright enough to see even when the sky is light. It spends about half its time above our horizon during the day. So on many mornings and afternoons, if you look up, you can spot it as a pale shape in the blue sky.'] },
  { id: 'moon-far', topic: 'Moon', q: 'How far away is the Moon?', alt: 'distance to the moon|how far is the moon|how long to get to the moon|moon distance', a: ['leo', 'The Moon is about 384,000 kilometres away. Light from the Moon reaches us in just over one second. The Apollo astronauts took about three days to get there.'] },
  { id: 'moon-landing', topic: 'Moon', q: 'Who first walked on the Moon?', alt: 'first person on the moon|neil armstrong|moon landing|apollo 11|who landed on the moon|1969', a: ['leo', 'Neil Armstrong was the first person to walk on the Moon, on 20 July 1969, during the Apollo 11 mission. Buzz Aldrin joined him soon after. Armstrong said that one small step for a man was one giant leap for mankind.'] },
  { id: 'moon-how-many-people', topic: 'Moon', q: 'How many people have walked on the Moon?', alt: 'people on the moon|how many astronauts went to the moon|moonwalkers|been to the moon', a: ['leo', 'Twelve people have walked on the Moon, all between 1969 and 1972. They were all American astronauts on the Apollo missions. They collected moon rocks, drove a moon buggy and even played golf there.'] },
  { id: 'moon-footprints', topic: 'Moon', q: 'Are the footprints still on the Moon?', alt: 'moon footprints|footprints on the moon|do footprints stay on the moon|footprint', a: ['leo', 'Yes. The Moon has no wind or rain to blow or wash them away. So the footprints left by the astronauts could last for millions of years, unless a tiny space rock lands on them.'] },
  { id: 'moon-far-side', topic: 'Moon', q: 'What is on the far side of the Moon?', alt: 'dark side of the moon|far side of the moon|back of the moon|other side of the moon|why do we only see one side of the moon', a: ['leo', 'The Moon always shows us the same face, because it spins at just the right speed as it goes around us. The far side is not dark, it gets sunshine too. It has even more craters, and a Chinese rover landed there in 2019.'] },
  { id: 'moon-gravity', topic: 'Moon', q: 'Could I jump high on the Moon?', alt: 'moon gravity|jumping on the moon|gravity on the moon|bounce on the moon|weigh on the moon', a: ['leo', 'Yes. Gravity on the Moon is only about a sixth as strong as on Earth. You could jump about six times higher than you can at home. Astronauts found it was easiest to get around by bouncing like kangaroos.'] },
  { id: 'moon-big', topic: 'Moon', q: 'How big is the Moon?', alt: 'size of the moon|is the moon big|moon size|how big is the moon compared to earth', a: ['leo', 'The Moon is about a quarter as wide as Earth. If Earth were a football, the Moon would be about the size of a tennis ball. It is the fifth biggest moon in the Solar System.'] },
  { id: 'moon-made', topic: 'Moon', q: 'How was the Moon made?', alt: 'where did the moon come from|how did the moon form|moon formed|how did we get the moon', a: ['leo', 'Scientists think that long ago a planet about the size of Mars crashed into the young Earth. Lots of rock was thrown into space, and it gathered together to make the Moon. So the Moon is a bit like a piece of Earth.'] },
  { id: 'moon-light', topic: 'Moon', q: 'Does the Moon make its own light?', alt: 'why does the moon glow|why is the moon bright|moonlight|does the moon shine', a: ['leo', 'No. Moonlight is really sunlight bouncing off the Moon, a bit like a mirror. The Moon is actually quite dark grey, about as dark as an old road, but it looks bright against the black night sky.'] },
  { id: 'moon-tides', topic: 'Moon', q: 'Does the Moon make the tides?', alt: 'tides|why does the sea go in and out|moon and the sea|high tide|low tide', a: ['leo', 'Yes. The gravity of the Moon gently pulls on the oceans, making them bulge a little. As Earth spins, the beaches pass through these bulges, so the sea comes in and goes out about twice a day.'] },
  { id: 'moon-go-back', topic: 'Moon', q: 'Are people going back to the Moon?', alt: 'artemis|going back to the moon|next moon landing|moon base|when will people go to the moon again', a: ['leo', 'Yes. NASA has a programme called Artemis that plans to take astronauts back to the Moon, including the first woman to walk there. Countries like China also plan Moon missions. One day there may even be a base near the south pole of the Moon.'] },
  { id: 'moon-away', topic: 'Moon', q: 'Is the Moon moving away from Earth?', alt: 'moon moving away|moon getting further|will the moon leave', a: ['leo', 'Yes, but very slowly. The Moon drifts about 4 centimetres further away each year, about as fast as your fingernails grow. It will stay our friendly neighbour for a very, very long time.'] },
  { id: 'moon-blue', topic: 'Moon', q: 'What is a blue moon?', alt: 'blue moon|once in a blue moon|is the moon ever blue|harvest moon|supermoon', a: ['leo', 'A blue moon is the name for an extra full moon, like a second one in the same month. It is not really blue. A supermoon is when a full moon happens while the Moon is a bit closer to us, so it looks slightly bigger and brighter.'] },

  /* ---------------- Earth ---------------- */
  { id: 'earth-seasons', topic: 'Earth', q: 'Why do we have seasons?', alt: 'seasons|why is it cold in winter|why is summer hot|why are there seasons|winter and summer|seesons', a: ['leo', 'Earth is tilted a little, like a spinning top leaning over. For part of the year our half of Earth leans towards the Sun, giving us long, warm summer days. Later it leans away, and we get short, chilly winter days.'] },
  { id: 'earth-day-night', topic: 'Earth', q: 'Why do we have day and night?', alt: 'day and night|why does it get dark|why is it night|where does the sun go|why is there night time', a: ['leo', 'Earth spins round like a top, once every 24 hours. When your side of Earth faces the Sun, it is daytime. When your side turns away, it is night, and children on the other side of the world are waking up.'] },
  { id: 'earth-round', topic: 'Earth', q: 'How do we know Earth is round?', alt: 'is the earth flat|is earth round|why is the earth round|earth shape|flat earth', a: ['leo', 'Astronauts have taken photos of Earth from space, and it is a beautiful round ball. Long before that, people noticed that ships sink below the horizon bottom first, and that the shadow of Earth on the Moon is always curved.'] },
  { id: 'earth-gravity', topic: 'Earth', q: 'What is gravity?', alt: 'gravity|why do things fall|why dont we fall off the earth|what keeps us on the ground|gravaty', a: ['leo', 'Gravity is an invisible pull that every object has. The bigger something is, the stronger it pulls. Earth is so big that its gravity keeps your feet on the ground, makes dropped toys fall, and keeps the Moon going around us.'] },
  { id: 'earth-spin-feel', topic: 'Earth', q: 'Why can I not feel Earth spinning?', alt: 'is the earth spinning|how fast does earth spin|why cant we feel the earth move|earth spinning|earth moving', a: ['leo', 'Earth spins smoothly and steadily, and everything around you moves along with it, including the air. In the UK you are whizzing round at about 1,000 kilometres an hour. It is like being in a smooth train where you cannot feel the speed.'] },
  { id: 'earth-age', topic: 'Earth', q: 'How old is Earth?', alt: 'age of the earth|when was earth made|how old is the world|how old is our planet', a: ['leo', 'Earth is about 4.5 billion years old. If the whole history of Earth were squeezed into one day, people would only appear in the last few seconds before midnight. Dinosaurs would turn up at about 11 at night.'] },
  { id: 'earth-year', topic: 'Earth', q: 'Why is a year 365 days?', alt: 'how long is a year|why are there 365 days|leap year|how long does earth take to go round the sun|earth orbit', a: ['leo', 'A year is how long Earth takes to travel all the way around the Sun, which is about 365 and a quarter days. Those extra quarters add up, so every four years we add an extra day, the 29th of February. That is called a leap year.'] },
  { id: 'earth-air-space', topic: 'Earth', q: 'Where does space begin?', alt: 'where does space start|how high is space|edge of space|how far up is space|karman line', a: ['leo', 'Many scientists say space begins about 100 kilometres above our heads. That is about as far as driving from London to Brighton, but straight up. Above that the air is so thin that it is almost gone.'] },
  { id: 'earth-from-space', topic: 'Earth', q: 'What does Earth look like from space?', alt: 'earth from space|what colour is earth|blue marble|earth photo from space|pale blue dot', a: ['leo', 'From space, Earth looks like a shining blue marble with swirls of white cloud, green and brown land, and white ice at the poles. Astronauts say seeing it makes them feel how precious and beautiful our home is.'] },
  { id: 'earth-atmosphere', topic: 'Earth', q: 'What is the atmosphere?', alt: 'atmosphere|what is air|layers of air|why does earth have air|atmosfere', a: ['leo', 'The atmosphere is the blanket of air that wraps around Earth. It gives us oxygen to breathe, keeps us warm, and protects us from a lot of the strong sunlight. Compared to the size of Earth, it is as thin as the skin on an apple.'] },
  { id: 'earth-core', topic: 'Earth', q: 'What is in the middle of Earth?', alt: 'earth core|centre of the earth|what is inside the earth|center of the earth|earth layers', a: ['leo', 'Right in the middle of Earth is a ball of iron and nickel called the inner core. Scientists think it is about as hot as the surface of the Sun. Around it is a layer of liquid metal, then thick rock, and then the thin crust we live on.'] },
  { id: 'earth-magnet', topic: 'Earth', q: 'Is Earth a magnet?', alt: 'earth magnetic field|why does a compass work|magnetic field|is the earth magnetic', a: ['leo', 'Yes. The swirling liquid metal deep inside Earth turns it into a giant magnet. That is why a compass needle points north. The magnetic field also acts like an invisible shield that protects us from the solar wind.'] },
  { id: 'earth-speed-orbit', topic: 'Earth', q: 'How fast does Earth go around the Sun?', alt: 'earth speed|how fast is earth moving|speed of earth|earth orbit speed', a: ['leo', 'Earth zooms around the Sun at about 107,000 kilometres an hour. That is much faster than any rocket launch. In the time it takes you to say hello, Earth has travelled around 30 kilometres.'] },
  { id: 'earth-only-life', topic: 'Earth', q: 'Is Earth the only planet with water?', alt: 'water on other planets|is there water in space|where else is there water|water in space', a: ['leo', 'Earth is the only planet we know with oceans on its surface. But there is water in lots of places in space, frozen as ice on the Moon, Mars, comets and icy moons. Some moons, like Europa, even hide whole oceans under their ice.'] },

  /* ---------------- Mars ---------------- */
  { id: 'mars-red', topic: 'Mars', q: 'Why is Mars red?', alt: 'why is mars red|red planet|mars colour|why is mars orange|mars color|wy is mars red', a: ['leo', 'Mars is red because its rocks and dust contain lots of iron that has gone rusty. Wind blows this rusty dust all over the planet, and some even floats in the sky. That is why Mars is called the Red Planet.'] },
  { id: 'mars-facts', topic: 'Mars', q: 'What is Mars like?', alt: 'mars|tell me about mars|mars facts|marz|the red planet', a: ['leo', 'Mars is a cold, dusty, rocky planet about half the size of Earth. It has mountains, valleys, polar ice caps and giant dust storms. A day there is just a little longer than ours, about 24 and a half hours.'] },
  { id: 'mars-live', topic: 'Mars', q: 'Could I live on Mars?', alt: 'can we live on mars|could people live on mars|move to mars|mars colony|living on mars|go to mars', a: ['leo', 'Not easily, but maybe one day. Mars is very cold, the air is too thin to breathe, and there is no liquid water on top. People would need special sealed homes, spacesuits and a way to grow food. Many scientists hope humans will visit Mars in your lifetime.'] },
  { id: 'mars-far', topic: 'Mars', q: 'How long does it take to get to Mars?', alt: 'how far is mars|distance to mars|travel to mars|how long to fly to mars|journey to mars', a: ['leo', 'A trip to Mars takes about seven months with the rockets we have today. Mars and Earth are both moving around the Sun, so we launch when they are close together, which happens about every two years.'] },
  { id: 'mars-rovers', topic: 'Mars', q: 'What robots are on Mars?', alt: 'mars rover|perseverance|curiosity rover|rovers on mars|robots on mars|ingenuity helicopter', a: ['leo', 'Robot explorers called rovers drive around Mars taking pictures and studying rocks. Curiosity landed in 2012 and Perseverance landed in 2021. Perseverance even brought a tiny helicopter called Ingenuity, the first aircraft to fly on another planet.'] },
  { id: 'mars-moons', topic: 'Mars', q: 'Does Mars have moons?', alt: 'mars moons|phobos|deimos|how many moons does mars have', a: ['leo', 'Mars has two small moons called Phobos and Deimos. They are lumpy, like potatoes, and much smaller than our Moon. Scientists think they might be captured asteroids, or pieces thrown up from a big crash on Mars.'] },
  { id: 'mars-mountain', topic: 'Mars', q: 'What is the biggest mountain on Mars?', alt: 'olympus mons|biggest volcano|tallest mountain in the solar system|mars volcano|mountain on mars', a: ['leo', 'Olympus Mons is a giant volcano on Mars, and the tallest one we know of in the Solar System. It is about 22 kilometres high, more than twice as tall as Mount Everest. It is about 600 kilometres wide, roughly the length of England.'] },
  { id: 'mars-cold', topic: 'Mars', q: 'How cold is Mars?', alt: 'mars temperature|is mars hot|is mars cold|how hot is mars|weather on mars', a: ['leo', 'Mars is usually very cold, about minus 60 degrees Celsius on average. On a summer afternoon near the middle it can reach about 20 degrees, but at night it drops far below freezing. You would need a very warm spacesuit.'] },
  { id: 'mars-water', topic: 'Mars', q: 'Is there water on Mars?', alt: 'water on mars|did mars have oceans|ice on mars|rivers on mars', a: ['leo', 'There is lots of frozen water on Mars, in its ice caps and under the ground. Long ago Mars had rivers and lakes, and rovers have found dried up riverbeds and pebbles smoothed by flowing water. Today it is too cold and thin aired for water to stay liquid on top.'] },
  { id: 'mars-sunset', topic: 'Mars', q: 'What colour is a sunset on Mars?', alt: 'mars sunset|blue sunset|sky on mars|what colour is the sky on mars', a: ['leo', 'On Mars it is the other way round from Earth. The daytime sky looks a dusty butterscotch colour, and sunsets glow blue. That is because the fine dust in the air scatters light differently from our air.'] },

  /* ---------------- Pluto ---------------- */
  { id: 'pluto-not-planet', topic: 'Pluto', q: 'Why is Pluto not a planet anymore?', alt: 'is pluto a planet|why isnt pluto a planet|pluto dwarf planet|pluto demoted|why is pluto not a planet|pluto not planet|pluto planet', a: ['leo', 'In 2006, astronomers agreed new rules for what counts as a planet. A planet must clear other objects out of its path around the Sun, and Pluto shares its path with lots of icy objects. So Pluto became a dwarf planet. Lots of people still love it just as much.'] },
  { id: 'pluto-heart', topic: 'Pluto', q: 'Why does Pluto have a heart?', alt: 'pluto heart|heart on pluto|heart shape on pluto|tombaugh regio|pluto love heart', a: ['leo', 'The heart on Pluto is a huge pale area of frozen ice, named Tombaugh Regio. The left side is a giant smooth plain of nitrogen ice, about as wide as France. Scientists think the ice slowly moves and churns, keeping it fresh and bright.'] },
  { id: 'pluto-new-horizons', topic: 'Pluto', q: 'Has a spacecraft been to Pluto?', alt: 'new horizons|spacecraft to pluto|who visited pluto|pluto photos|first pictures of pluto', a: ['leo', 'Yes. A NASA spacecraft called New Horizons launched in 2006 and zoomed past Pluto on 14 July 2015. It sent back the first close up pictures, showing the heart, icy mountains and a hazy blue sky. It is still travelling out into deep space today.'] },
  { id: 'pluto-charon', topic: 'Pluto', q: 'What is Charon?', alt: 'charon|pluto moon|plutos moon|sharon moon|moons of pluto|how many moons does pluto have', a: ['leo', 'Charon is the biggest moon of Pluto. It is about half as wide as Pluto, so they look like a pair of dancing partners swinging around each other. Pluto has four other small moons too, called Nix, Hydra, Kerberos and Styx.'] },
  { id: 'pluto-cold', topic: 'Pluto', q: 'How cold is Pluto?', alt: 'pluto temperature|is pluto cold|how cold is it on pluto|pluto freezing|is pluto hot', a: ['leo', 'Pluto is incredibly cold, about minus 230 degrees Celsius. That is so cold that nitrogen, which is a gas in our air, freezes solid there. The mountains on Pluto are made of water ice that is as hard as rock.'] },
  { id: 'pluto-far', topic: 'Pluto', q: 'How far away is Pluto?', alt: 'distance to pluto|how far is pluto|how long to get to pluto|pluto distance', a: ['leo', 'Pluto is on average about 6 billion kilometres from the Sun, about 40 times further than Earth. Sunlight takes around five and a half hours to get there. New Horizons, one of the fastest spacecraft ever, took nine and a half years to reach it.'] },
  { id: 'pluto-visit', topic: 'Pluto', q: 'Could I visit Pluto?', alt: 'can people go to pluto|can i go to pluto|stand on pluto|land on pluto|live on pluto|walk on pluto', a: ['leo', 'Not yet, as it is very far and very cold. But if you could stand there, you would feel super light and could leap really high. The Sun would look like a very bright star, and Charon would hang still in the sky. Maybe a future explorer will go one day.'] },
  { id: 'pluto-found', topic: 'Pluto', q: 'Who discovered Pluto?', alt: 'who found pluto|when was pluto discovered|clyde tombaugh|discovery of pluto|pluto discovered', a: ['leo', 'Pluto was discovered in 1930 by Clyde Tombaugh, a young astronomer in Arizona. He compared photos of the night sky taken days apart and spotted a tiny dot that had moved. Some of his ashes travelled to Pluto on New Horizons.'] },
  { id: 'pluto-name', topic: 'Pluto', q: 'Who named Pluto?', alt: 'how did pluto get its name|venetia burney|who chose the name pluto|why is pluto called pluto|pluto name', a: ['leo', 'Pluto was named by an 11 year old girl from Oxford called Venetia Burney. She loved myths and suggested Pluto, the Roman god of the underworld, because the new world was so dark and far away. Her idea was chosen. A child named a world.'] },
  { id: 'pluto-size', topic: 'Pluto', q: 'How big is Pluto?', alt: 'pluto size|is pluto small|how big is pluto compared to earth|is pluto smaller than the moon', a: ['leo', 'Pluto is small, about 2,400 kilometres wide. That is smaller than our Moon and narrower than the width of Australia. Even so, it is one of the biggest things in the far icy region beyond Neptune.'] },
  { id: 'pluto-year', topic: 'Pluto', q: 'How long is a year on Pluto?', alt: 'pluto year|pluto day|how long is a day on pluto|pluto orbit|birthday on pluto', a: ['leo', 'One year on Pluto lasts 248 Earth years, so nobody on Earth has seen Pluto go all the way round since it was found. A day on Pluto is about six and a half Earth days. You would have a very long wait for your birthday.'] },
  { id: 'pluto-kuiper', topic: 'Pluto', q: 'Where does Pluto live?', alt: 'kuiper belt|what is the kuiper belt|where is pluto|pluto neighbours|whats near pluto', a: ['leo', 'Pluto lives in the Kuiper Belt, a huge ring of icy worlds beyond Neptune. It is like a frosty version of the asteroid belt. Pluto is one of the biggest things there, along with other dwarf planets like Eris and Makemake.'] },
  { id: 'pluto-sky', topic: 'Pluto', q: 'Does Pluto have air?', alt: 'pluto atmosphere|blue sky on pluto|does pluto have weather|snow on pluto|air on pluto', a: ['leo', 'Pluto has a very thin layer of air, mostly nitrogen. New Horizons saw that it makes a beautiful blue haze around the planet. As Pluto moves further from the Sun, scientists think some of this air may freeze and fall as frost.'] },

  /* ---------------- Stars ---------------- */
  { id: 'stars-twinkle', topic: 'Stars', q: 'Why do stars twinkle?', alt: 'twinkle twinkle|why do stars sparkle|stars twinkling|why do stars flicker|twinkel', a: ['leo', 'Stars twinkle because their light passes through the moving, wobbly air above us. The air bends the light this way and that, so the star seems to sparkle. Out in space, astronauts see stars shining steadily without twinkling.'] },
  { id: 'stars-what', topic: 'Stars', q: 'What are stars made of?', alt: 'what is a star|stars made of|what are stars|star made of|what is a star made from', a: ['leo', 'Stars are giant balls of hot, glowing gas, mostly hydrogen and helium. Deep inside, they squash hydrogen together to make light and heat, just like our Sun. In fact, our Sun is a star, it is just the closest one.'] },
  { id: 'stars-how-many', topic: 'Stars', q: 'How many stars are there?', alt: 'number of stars|how many stars in the sky|how many stars in the universe|count the stars|how many stars can i see', a: ['leo', 'On a dark night you might see about 2,000 or 3,000 stars with just your eyes. Our galaxy has hundreds of billions of stars. Scientists think the whole universe may have more stars than there are grains of sand on all the beaches of Earth.'] },
  { id: 'stars-colours', topic: 'Stars', q: 'Why are stars different colours?', alt: 'star colours|blue stars|red stars|what colour are stars|star color', a: ['leo', 'The colour of a star tells us how hot it is. Red stars are the coolest, yellow stars like our Sun are in the middle, and blue white stars are the hottest. It is the opposite of the taps at home, where blue means cold.'] },
  { id: 'stars-shooting', topic: 'Stars', q: 'What is a shooting star?', alt: 'shooting star|falling star|meteor|wish on a shooting star|shooting stars|meteor shower', a: ['leo', 'A shooting star is not really a star. It is a tiny bit of space dust, often smaller than a grain of sand, burning up as it zips into our air very fast. The bright streak lasts only a second, so make your wish quickly.'] },
  { id: 'stars-nearest', topic: 'Stars', q: 'What is the nearest star?', alt: 'closest star|nearest star to earth|proxima centauri|next closest star', a: ['leo', 'The nearest star is our Sun. The next nearest is Proxima Centauri, about 4.2 light years away. That means its light takes over four years to reach us. With our fastest spacecraft, the journey would still take thousands of years.'] },
  { id: 'stars-constellations', topic: 'Stars', q: 'What are constellations?', alt: 'constellation|star patterns|big dipper|orion|plough|star pictures|constelation', a: ['leo', 'Constellations are patterns of stars that people have joined up into pictures, like dot to dot. There are 88 official ones. In the UK, look for Orion the hunter in winter, with three stars in a row for his belt, and the Plough, which looks like a saucepan.'] },
  { id: 'stars-north-star', topic: 'Stars', q: 'What is the North Star?', alt: 'north star|pole star|polaris|how do i find north|star that points north', a: ['leo', 'The North Star, called Polaris, sits almost exactly above the North Pole of Earth. While other stars seem to wheel around the sky, it barely moves. Sailors used it to find north. You can find it by following the two end stars of the Plough.'] },
  { id: 'stars-born', topic: 'Stars', q: 'How are stars born?', alt: 'how are stars made|where do stars come from|baby stars|star birth|nebula', a: ['leo', 'Stars are born inside giant clouds of gas and dust called nebulas. Gravity pulls some of the gas into a tight ball that gets hotter and hotter, until it starts to shine. Big clouds can make whole families of stars at once.'] },
  { id: 'stars-die', topic: 'Stars', q: 'Do stars die?', alt: 'what happens when a star dies|how do stars die|star death|do stars last forever|dying star', a: ['leo', 'Stars do not last forever, but they shine for millions or billions of years. Stars like our Sun gently puff away their outer layers and leave a small glowing core called a white dwarf. Their gas floats off and can help make new stars.'] },
  { id: 'stars-supernova', topic: 'Stars', q: 'What is a supernova?', alt: 'supernova|exploding star|star explosion|super nova', a: ['leo', 'A supernova is when a very big star reaches the end of its life and explodes. For a short time it can shine brighter than a whole galaxy. The explosion spreads new ingredients, like iron and gold, out into space.'] },
  { id: 'stars-stardust', topic: 'Stars', q: 'Are we made of stardust?', alt: 'made of stars|stardust|are people made of stars|star stuff', a: ['leo', 'Yes, in a way. Much of the stuff in your body, like the calcium in your bones and the iron in your blood, was made inside stars long ago. When those stars ended, they scattered it into space. So you really are made of star stuff.'] },
  { id: 'stars-biggest', topic: 'Stars', q: 'What is the biggest star?', alt: 'biggest star|largest star|betelgeuse|uy scuti|giant star', a: ['leo', 'The biggest stars are called red supergiants. Some are so huge that if one sat where our Sun is, it would stretch out past Jupiter. Betelgeuse, the red shoulder of Orion, is one you can see from the UK.'] },
  { id: 'stars-day', topic: 'Stars', q: 'Where do the stars go in the daytime?', alt: 'stars in the day|why cant i see stars in the day|daytime stars|do stars disappear', a: ['leo', 'The stars are still there in the daytime. The Sun is so bright that it lights up the sky and hides their gentle glow, like trying to see a torch in a sunny garden. When the Sun sets, they appear again.'] },
  { id: 'stars-light-old', topic: 'Stars', q: 'Are some stars already gone?', alt: 'dead stars still shining|are the stars i see still there|old starlight|is that star dead', a: ['leo', 'Starlight takes a long time to reach us, so we see stars as they were in the past. Almost all the stars you see at night are still shining today. Only very rarely might one have changed since its light set off.'] },
  { id: 'stars-sun-star', topic: 'Stars', q: 'Is the Sun a big star or a small star?', alt: 'is the sun a big star|is the sun an average star|sun compared to other stars|medium star', a: ['leo', 'The Sun is a medium sized star. Some stars are hundreds of times bigger, and lots are smaller and dimmer. Most stars in our galaxy are small red dwarfs, so the Sun is actually brighter than most of its neighbours.'] },
  { id: 'stars-neutron', topic: 'Stars', q: 'What is a neutron star?', alt: 'neutron star|pulsar|what is a pulsar|neutron', a: ['leo', 'A neutron star is the squashed leftover middle of a giant star after it explodes. It is about the size of a city but heavier than the Sun. A teaspoon of it would weigh as much as a mountain. Some spin very fast and flash like lighthouses.'] },
  { id: 'stars-wish', topic: 'Stars', q: 'Can I name a star?', alt: 'name a star|buy a star|how do stars get names|star names', a: ['leo', 'Stars get official names from a big group of astronomers called the International Astronomical Union. You cannot really buy a star. But you can give a favourite star your own special name in your heart, and nobody can stop you.'] },

  /* ---------------- Galaxies ---------------- */
  { id: 'galaxy-milky-way', topic: 'Galaxies', q: 'What is the Milky Way?', alt: 'milky way|our galaxy|what galaxy do we live in|milky way galaxy|milkyway', a: ['leo', 'The Milky Way is our home galaxy, a giant spiral of hundreds of billions of stars. Our Sun is one of them, out in one of the spiral arms. On a very dark night you can see it as a faint, milky band across the sky.'] },
  { id: 'galaxy-what', topic: 'Galaxies', q: 'What is a galaxy?', alt: 'galaxy|what are galaxies|galaxys|galaxie|define galaxy', a: ['leo', 'A galaxy is an enormous family of stars, gas and dust held together by gravity. Some are spirals like pinwheels, some are round or egg shaped, and some are messy blobs. Each one can hold billions of stars.'] },
  { id: 'galaxy-how-many', topic: 'Galaxies', q: 'How many galaxies are there?', alt: 'number of galaxies|how many galaxies in the universe|lots of galaxies|count galaxies', a: ['leo', 'Scientists think there are hundreds of billions of galaxies, and maybe even more than a trillion. When the Hubble telescope stared at a tiny dark patch of sky, it found thousands of galaxies hiding there.'] },
  { id: 'galaxy-andromeda', topic: 'Galaxies', q: 'What is the Andromeda galaxy?', alt: 'andromeda|andromeda galaxy|nearest galaxy|closest galaxy|andromida', a: ['leo', 'Andromeda is the nearest big galaxy to ours, about 2.5 million light years away. It is a giant spiral like the Milky Way. On a very dark night it is the furthest thing you can see with just your eyes, a faint fuzzy smudge.'] },
  { id: 'galaxy-crash', topic: 'Galaxies', q: 'Will Andromeda crash into us?', alt: 'andromeda collision|galaxies crashing|will galaxies collide|milky way and andromeda', a: ['leo', 'Scientists think the Milky Way and Andromeda might drift together billions of years from now. Even then, the stars are so far apart that they would hardly ever bump. The two galaxies would gently mix into one bigger galaxy.'] },
  { id: 'galaxy-size', topic: 'Galaxies', q: 'How big is the Milky Way?', alt: 'size of the milky way|how big is our galaxy|milky way size|how wide is the galaxy', a: ['leo', 'The Milky Way is about 100,000 light years across. Even light, which could go around Earth more than seven times in one second, takes that many years to cross it. The Sun takes about 230 million years to go once around the middle.'] },
  { id: 'galaxy-middle', topic: 'Galaxies', q: 'What is in the middle of the Milky Way?', alt: 'centre of the milky way|middle of our galaxy|sagittarius a|black hole in the milky way|center of the galaxy', a: ['leo', 'Right in the middle of the Milky Way is a supermassive black hole called Sagittarius A star. It is about 4 million times heavier than the Sun. We are very, very far from it, so it is nothing to worry about.'] },
  { id: 'galaxy-shapes', topic: 'Galaxies', q: 'What shapes are galaxies?', alt: 'types of galaxies|spiral galaxy|elliptical galaxy|galaxy shapes|kinds of galaxies', a: ['leo', 'Galaxies come in three main shapes. Spiral galaxies look like swirling pinwheels, elliptical galaxies look like fuzzy eggs, and irregular galaxies have no neat shape at all. The Milky Way is a spiral with a bar of stars across its middle.'] },

  /* ---------------- Black holes ---------------- */
  { id: 'bh-what', topic: 'Black holes', q: 'What is a black hole?', alt: 'black hole|what are black holes|blackhole|black hole meaning|blak hole', a: ['leo', 'A black hole is a place in space where gravity is so strong that nothing can escape, not even light. That is why it looks black. It is not really a hole, it is a huge amount of stuff squeezed into a very tiny space.'] },
  { id: 'bh-made', topic: 'Black holes', q: 'How are black holes made?', alt: 'how do black holes form|where do black holes come from|black hole made|how is a black hole born', a: ['leo', 'Many black holes are made when a very big star runs out of fuel. Its middle squashes down smaller and smaller until it becomes a black hole. Giant ones in the middles of galaxies grew over billions of years.'] },
  { id: 'bh-earth', topic: 'Black holes', q: 'Could a black hole swallow Earth?', alt: 'will a black hole eat earth|are black holes dangerous|black hole near earth|black hole scary', a: ['leo', 'No need to worry. The nearest black holes are many light years away, far too far to affect us. Black holes do not hoover up everything around them either. If something is not very close, it can travel past safely.'] },
  { id: 'bh-inside', topic: 'Black holes', q: 'What is inside a black hole?', alt: 'inside a black hole|what happens in a black hole|go into a black hole|fall into a black hole', a: ['leo', 'Nobody knows for sure, because no light comes out to tell us. It is one of the biggest mysteries in science. Scientists use clever maths to try to work it out. Maybe one day you will help solve it.'] },
  { id: 'bh-photo', topic: 'Black holes', q: 'Has anyone taken a picture of a black hole?', alt: 'black hole picture|black hole photo|image of a black hole|what does a black hole look like', a: ['leo', 'Yes. In 2019, scientists linked telescopes all around the world to take the first picture of a black hole, in a galaxy called M87. It looked like a glowing orange doughnut with a dark middle. In 2022 they did the same for the one in our galaxy.'] },
  { id: 'bh-size', topic: 'Black holes', q: 'How big are black holes?', alt: 'biggest black hole|size of a black hole|small black hole|supermassive black hole', a: ['leo', 'Some black holes are only a few times heavier than the Sun and could fit inside a city. Supermassive ones in the middles of galaxies can be millions or billions of times heavier than the Sun. Black holes come in lots of sizes.'] },
  { id: 'bh-see', topic: 'Black holes', q: 'How do we find black holes if they are black?', alt: 'how do we see black holes|can you see a black hole|finding black holes|how do we know black holes exist', a: ['leo', 'We look at what is happening around them. Gas swirling into a black hole gets very hot and glows brightly. Stars near a black hole whizz around it very fast. Scientists can even feel tiny ripples in space when two black holes merge.'] },
  { id: 'bh-wormhole', topic: 'Black holes', q: 'What is a wormhole?', alt: 'wormhole|worm hole|tunnel through space|are wormholes real', a: ['leo', 'A wormhole is an idea for a shortcut tunnel through space, connecting two faraway places. Some maths says they could be possible, but nobody has ever found one. For now, wormholes live in science fiction stories and in the imaginations of scientists.'] },

  /* ---------------- Astronauts ---------------- */
  { id: 'astro-first', topic: 'Astronauts', q: 'Who was the first person in space?', alt: 'first person in space|yuri gagarin|first astronaut|first man in space|1961|who went to space first', a: ['leo', 'The first person in space was Yuri Gagarin, on 12 April 1961. He flew once around Earth in a little spacecraft called Vostok 1, and the whole trip took about an hour and three quarters. He became famous all over the world.'] },
  { id: 'astro-first-woman', topic: 'Astronauts', q: 'Who was the first woman in space?', alt: 'first woman in space|valentina tereshkova|first lady in space|first girl in space', a: ['leo', 'The first woman in space was Valentina Tereshkova, in June 1963. She circled Earth 48 times in nearly three days. Since then, lots of brilliant women have flown to space, lived on the space station and even commanded it.'] },
  { id: 'astro-tim-peake', topic: 'Astronauts', q: 'Who is Tim Peake?', alt: 'tim peake|british astronaut|uk astronaut|astronaut from england|tim peak', a: ['leo', 'Tim Peake is a British astronaut who lived on the International Space Station for six months, from December 2015 to June 2016. He did a spacewalk, ran the London Marathon on a treadmill in space, and talked to lots of schools by radio.'] },
  { id: 'astro-first-brit', topic: 'Astronauts', q: 'Who was the first British person in space?', alt: 'first british astronaut|helen sharman|first brit in space|first person from the uk in space', a: ['leo', 'The first British person in space was Helen Sharman, in 1991. She was a chemist who answered a radio advert looking for astronauts. She spent about eight days on a space station called Mir, doing science experiments.'] },
  { id: 'astro-become', topic: 'Astronauts', q: 'How do I become an astronaut?', alt: 'become an astronaut|how to be an astronaut|i want to be an astronaut|can i be an astronaut|astronaut job|how do you become an astronot', a: ['leo', 'Astronauts usually study subjects like science, maths, engineering or medicine, and they stay fit and healthy. They need to be good at working in a team and staying calm. Keep asking questions and learning, and you could be one too.'] },
  { id: 'astro-food', topic: 'Astronauts', q: 'What do astronauts eat?', alt: 'space food|astronaut food|what do they eat in space|food in space|astronauts eat', a: ['leo', 'Astronauts eat lots of normal food, like pasta, curry, fruit and even chocolate. Much of it comes in pouches. They use tortilla wraps instead of bread, because bread crumbs would float about and get into everything.'] },
  { id: 'astro-toilet', topic: 'Astronauts', q: 'How do astronauts go to the toilet?', alt: 'space toilet|toilet in space|how do astronauts poo|how do astronauts wee|loo in space|bathroom in space', a: ['leo', 'Space toilets use air that sucks everything away, a bit like a gentle vacuum cleaner, so nothing floats off. On the space station, wee is even cleaned and turned back into drinking water. Astronauts say it tastes just like normal water.'] },
  { id: 'astro-sleep', topic: 'Astronauts', q: 'How do astronauts sleep?', alt: 'sleeping in space|where do astronauts sleep|space bed|beds in space|do astronauts sleep', a: ['leo', 'Astronauts sleep in sleeping bags tied to the wall of a tiny cabin, so they do not float around. With no up or down, they can sleep any way round. Some say it is the comfiest sleep ever, like floating on a cloud.'] },
  { id: 'astro-shower', topic: 'Astronauts', q: 'Do astronauts have showers?', alt: 'shower in space|how do astronauts wash|bath in space|washing in space|how do astronauts keep clean', a: ['leo', 'There are no showers on the space station, because water would float about in blobs. Astronauts wash with wet cloths and use special shampoo that does not need rinsing. They dry off with a towel, and the water is collected and recycled.'] },
  { id: 'astro-float', topic: 'Astronauts', q: 'Why do astronauts float?', alt: 'floating in space|why is there no gravity in space|zero gravity|weightless|how do astronauts float|why do you float in space', a: ['leo', 'Astronauts on the space station are actually falling around Earth all the time, but they move sideways so fast that they keep missing it. Because they fall together with their spacecraft, they float inside it. Gravity is still there, it just does not feel like it.'] },
  { id: 'astro-float-feel', topic: 'Astronauts', q: 'What does floating in space feel like?', alt: 'what is it like to float|how does it feel in space|does floating feel weird|feel weightless', a: ['leo', 'Astronauts say floating feels amazing, like swimming without water. You can do somersaults with one push and fly across a room with a gentle kick. For the first few days some feel a bit dizzy, but they soon get used to it.'] },
  { id: 'astro-iss', topic: 'Astronauts', q: 'What is the International Space Station?', alt: 'iss|space station|international space station|where do astronauts live|space house', a: ['leo', 'The International Space Station is a home and science lab flying about 400 kilometres above Earth. It is about as big as a football pitch, and countries worked together to build it. People have lived on it all the time since the year 2000.'] },
  { id: 'astro-iss-fast', topic: 'Astronauts', q: 'How fast does the space station go?', alt: 'how fast is the iss|iss speed|space station speed|can i see the space station', a: ['leo', 'The space station zooms around Earth at about 28,000 kilometres an hour, going all the way round in about 90 minutes. So astronauts see about 16 sunrises every day. You can often see it from your garden as a bright, steady dot gliding across the sky.'] },
  { id: 'astro-spacesuit', topic: 'Astronauts', q: 'Why do astronauts wear spacesuits?', alt: 'spacesuit|space suit|what is a spacesuit for|astronaut suit|space helmet', a: ['leo', 'A spacesuit is like a tiny spaceship shaped like a person. It gives the astronaut air to breathe, keeps them at a comfy temperature, and protects them from the Sun and tiny bits of dust. A spacewalk suit even has its own little jetpack for emergencies.'] },
  { id: 'astro-spacewalk', topic: 'Astronauts', q: 'What is a spacewalk?', alt: 'spacewalk|space walk|going outside in space|first spacewalk|walk in space', a: ['leo', 'A spacewalk is when an astronaut goes outside the spacecraft in a spacesuit, usually to fix or build something. They clip on with safety lines so they stay attached. The first spacewalk was by Alexei Leonov in 1965.'] },
  { id: 'astro-taller', topic: 'Astronauts', q: 'Do astronauts grow taller in space?', alt: 'grow taller in space|astronauts taller|do you get taller in space|height in space', a: ['leo', 'Yes. Without gravity squashing their backbones, astronauts can grow up to about 5 centimetres taller in space. Their spacesuits are made with room for this. When they come home to Earth, they shrink back to their normal height.'] },
  { id: 'astro-exercise', topic: 'Astronauts', q: 'Do astronauts exercise in space?', alt: 'exercise in space|gym in space|why do astronauts exercise|treadmill in space', a: ['leo', 'Yes, about two hours every day. Floating is so easy that muscles and bones get weaker without work. So astronauts use a treadmill with straps, an exercise bike and a special weightlifting machine to stay strong.'] },
  { id: 'astro-what-do', topic: 'Astronauts', q: 'What do astronauts do all day?', alt: 'astronaut job|what do astronauts do|astronaut day|a day in the life of an astronaut|astronaut work', a: ['leo', 'Astronauts on the space station do science experiments, look after the station, fix things and exercise. They also talk to scientists and school children on Earth. In their free time they love looking out of the window at Earth.'] },
  { id: 'astro-drink', topic: 'Astronauts', q: 'How do astronauts drink?', alt: 'drinking in space|water in space|can you drink in space|drinks in space|water blob', a: ['leo', 'Astronauts drink from pouches with straws. If they squeeze water out, it floats in a wobbly ball. Some astronauts like to catch floating water balls with their mouths, like a goldfish.'] },
  { id: 'astro-burp', topic: 'Astronauts', q: 'Can you burp in space?', alt: 'burp in space|burping in space|can astronauts burp|burb in space|fart in space', a: ['leo', 'Burping in space is tricky. On Earth, gas rises to the top of your tummy, but in space it gets mixed up with your food and drink. So astronauts often do wet burps. That is one reason fizzy drinks are not sent to space.'] },
  { id: 'astro-cry', topic: 'Astronauts', q: 'Can you cry in space?', alt: 'cry in space|tears in space|crying in space|do tears fall in space', a: ['leo', 'You can cry in space, but tears do not fall down your cheeks. They gather into a wobbly ball of water stuck to your eye. Astronauts gently wipe them away with a cloth. Happy tears at seeing Earth are very common.'] },
  { id: 'astro-pizza', topic: 'Astronauts', q: 'Is there pizza in space?', alt: 'pizza in space|can you eat pizza in space|space pizza|pizza delivery in space', a: ['leo', 'Yes. Astronauts on the space station have made their own pizzas with flatbreads, sauce and cheese. The toppings had to be held down carefully, or they floated away. They said it was one of their favourite space meals.'] },
  { id: 'astro-cake', topic: 'Astronauts', q: 'What would happen to a cake in space?', alt: 'cake in space|birthday cake in space|bake a cake in space|can you bake in space', a: ['leo', 'A cake would float, and every crumb would drift off around the room, which is not a good idea near computers. Astronauts have had birthday treats in space, but they choose soft foods that do not crumble. Candles are not allowed, because fire in space is a no no.'] },
  { id: 'astro-teeth', topic: 'Astronauts', q: 'How do astronauts brush their teeth?', alt: 'brush teeth in space|toothbrush in space|toothpaste in space|teeth in space', a: ['leo', 'Astronauts brush their teeth just like you, but with only a tiny bit of water. They cannot spit into a sink, so they either swallow the toothpaste or spit it into a towel. Then they tidy everything away so nothing floats off.'] },
  { id: 'astro-hair', topic: 'Astronauts', q: 'How do astronauts get a haircut?', alt: 'haircut in space|hair in space|why does hair stick up in space|cut hair in space', a: ['leo', 'Astronauts cut hair with clippers attached to a vacuum hose, which sucks up every little hair. Otherwise the hair would float everywhere. Long hair in space floats up around your head like a fluffy dandelion.'] },
  { id: 'astro-how-many', topic: 'Astronauts', q: 'How many people have been to space?', alt: 'people in space|how many astronauts are there|how many people went to space|astronauts count', a: ['leo', 'More than 600 people from over 40 countries have been to space. That is still a small group, about enough to fill a big school. There are usually around ten people living in space at any one time.'] },
  { id: 'astro-long', topic: 'Astronauts', q: 'What is the longest anyone has stayed in space?', alt: 'longest time in space|record in space|how long can astronauts stay in space|longest space mission', a: ['leo', 'The record for one trip is about 437 days, set by a Russian doctor called Valeri Polyakov in the 1990s. That is well over a year. Most astronauts on the space station stay for about six months.'] },
  { id: 'astro-scared', topic: 'Astronauts', q: 'Is it dangerous to go to space?', alt: 'is space dangerous|have astronauts died|do astronauts die|is it safe to go to space|space accident|astronaut die', a: ['leo', 'Space travel is carefully planned, and astronauts train for years to stay safe. Sadly, a small number of astronauts have died in accidents over the years. Engineers learned from each one to make spaceflight safer, and people remember those astronauts as heroes.'] },
  { id: 'astro-laika', topic: 'Astronauts', q: 'Have dogs been to space?', alt: 'dogs in space|laika|space dog|first dog in space|did a dog go to space|belka and strelka', a: ['leo', 'Yes. In 1957 a dog called Laika became the first animal to orbit Earth. She did not come home, and people remember her kindly as a brave pioneer. In 1960, two dogs called Belka and Strelka flew to space and came back home safely.'] },
  { id: 'astro-dog-astronaut', topic: 'Astronauts', q: 'Could a dog be an astronaut?', alt: 'can dogs be astronauts|dog astronaut|could my dog go to space|pets in space|cat in space', a: ['leo', 'Dogs did fly to space long ago, before people did, to help scientists check it was safe. Today, animals do not go up as astronauts. A dog would find floating very confusing, and there is nowhere for walkies. They are much happier at home.'] },
  { id: 'astro-animals', topic: 'Astronauts', q: 'What animals have been to space?', alt: 'animals in space|monkeys in space|first animal in space|space animals|spiders in space', a: ['leo', 'Lots of animals have been to space, including fruit flies, mice, fish, frogs, spiders, tortoises and even tiny water bears called tardigrades. In 1947, fruit flies became the first animals in space. They helped scientists learn how space affects living things.'] },

  /* ---------------- Rockets ---------------- */
  { id: 'rocket-how', topic: 'Rockets', q: 'How do rockets work?', alt: 'how does a rocket work|how do rockets fly|rocket science|how does a rocket go up|rockits', a: ['leo', 'A rocket burns fuel to make a huge blast of hot gas that shoots out of the bottom. Pushing the gas down pushes the rocket up. It is like letting go of a blown up balloon and watching it whizz away.'] },
  { id: 'rocket-tall', topic: 'Rockets', q: 'Why are rockets so tall?', alt: 'why are rockets big|why are rockets long|rocket size|biggest rocket|tallest rocket', a: ['leo', 'Most of a rocket is fuel tanks, because getting into space takes an enormous amount of fuel. Stacking the parts on top of each other makes a tall, thin shape that slices through the air. The Saturn V rocket that went to the Moon was 111 metres tall, taller than Big Ben.'] },
  { id: 'rocket-biggest', topic: 'Rockets', q: 'What is the biggest rocket ever?', alt: 'biggest rocket ever|starship|largest rocket|most powerful rocket|saturn v', a: ['leo', 'The biggest rocket ever flown is Starship, made by a company called SpaceX. It is more than 120 metres tall. Before that, the record holder for many years was the Saturn V, which carried astronauts to the Moon.'] },
  { id: 'rocket-fast', topic: 'Rockets', q: 'How fast do rockets go?', alt: 'rocket speed|how fast is a rocket|how fast to get to space|speed of a rocket', a: ['leo', 'To stay in orbit around Earth, a rocket has to reach about 28,000 kilometres an hour. That is about 30 times faster than a passenger jet. To escape Earth completely and head to the Moon or planets, it needs to go even faster, about 40,000 kilometres an hour.'] },
  { id: 'rocket-fastest', topic: 'Rockets', q: 'What is the fastest spacecraft?', alt: 'fastest spacecraft|fastest thing humans made|parker solar probe|fastest rocket|quickest spaceship', a: ['leo', 'The fastest spacecraft ever is the Parker Solar Probe, which flies close to the Sun. At top speed it goes about 690,000 kilometres an hour. At that speed you could fly from London to New York in about 30 seconds.'] },
  { id: 'rocket-voyager', topic: 'Rockets', q: 'What is Voyager?', alt: 'voyager|voyager 1|voyager 2|furthest spacecraft|golden record|furthest thing from earth', a: ['leo', 'Voyager 1 and Voyager 2 are two spacecraft launched in 1977 that visited the giant planets. Voyager 1 is now the furthest human made object, more than 24 billion kilometres away in interstellar space. Each carries a golden record with sounds and music from Earth.'] },
  { id: 'rocket-hubble', topic: 'Rockets', q: 'What is the Hubble telescope?', alt: 'hubble|hubble space telescope|space telescope|hubble pictures|hubbel', a: ['leo', 'The Hubble Space Telescope was launched in 1990 and orbits about 540 kilometres above Earth. Above the wobbly air, it takes super sharp pictures of planets, nebulas and faraway galaxies. Astronauts visited it five times to fix and upgrade it.'] },
  { id: 'rocket-jwst', topic: 'Rockets', q: 'What is the James Webb telescope?', alt: 'james webb|jwst|webb telescope|james web telescope|new space telescope', a: ['leo', 'The James Webb Space Telescope launched on Christmas Day 2021. It has a golden mirror 6.5 metres wide, made of 18 hexagons, and a sunshield as big as a tennis court. It sees heat light, which lets it spot the very first galaxies.'] },
  { id: 'rocket-satellite', topic: 'Rockets', q: 'What is a satellite?', alt: 'satellite|satellites|what do satellites do|sputnik|first satellite|how many satellites', a: ['leo', 'A satellite is anything that goes around a planet. The Moon is a natural one. Made satellites help with weather forecasts, maps, phones and television. The first was Sputnik 1 in 1957, and now there are more than ten thousand working ones.'] },
  { id: 'rocket-junk', topic: 'Rockets', q: 'What is space junk?', alt: 'space junk|space rubbish|space debris|litter in space', a: ['leo', 'Space junk is old rockets, broken satellites and little bits left in orbit around Earth. It whizzes round very fast, so scientists track it carefully and steer spacecraft out of the way. People are working on clever ways to tidy it up.'] },
  { id: 'rocket-land', topic: 'Rockets', q: 'Can rockets land again?', alt: 'reusable rockets|rocket landing|do rockets come back|rocket lands itself', a: ['leo', 'Some can. Companies like SpaceX make rocket boosters that fly back and land upright on their legs, like something from a film. Using them again saves lots of money. Astronaut capsules come home using parachutes.'] },
  { id: 'rocket-steer', topic: 'Rockets', q: 'How do spacecraft steer in space?', alt: 'steering in space|how do rockets turn|how do spaceships move in space|thrusters', a: ['leo', 'Spacecraft have small rocket jets called thrusters pointing in different directions. A quick puff from one pushes the spacecraft the other way. Some also use spinning wheels inside to turn themselves around slowly.'] },
  { id: 'rocket-countdown', topic: 'Rockets', q: 'Why do rockets have a countdown?', alt: 'countdown|10 9 8 7|why count down|blast off|lift off', a: ['leo', 'A countdown makes sure everyone and every machine is ready at exactly the right moment. During the countdown, the team checks hundreds of things. Then, three, two, one, lift off. You can do your own countdown to launch in this game.'] },
  { id: 'rocket-plane', topic: 'Rockets', q: 'Can an aeroplane fly to space?', alt: 'can a plane go to space|airplane to space|why cant planes go to space|jet to space', a: ['leo', 'A normal aeroplane cannot fly to space. Its wings need air to lift it and its engines need air to burn fuel, and the air gets too thin high up. Rockets carry their own oxygen, so they can keep pushing even where there is no air.'] },
  { id: 'rocket-to-iss', topic: 'Rockets', q: 'How long does it take to get to the space station?', alt: 'how long to get to space|flight to the iss|how long to reach the space station|how long to get to the iss', a: ['leo', 'Rockets reach space in less than ten minutes. Then the capsule has to catch up with the space station and dock gently. That can take from a few hours to about a day, depending on the plan.'] },
  { id: 'rocket-fuel', topic: 'Rockets', q: 'What fuel do rockets use?', alt: 'rocket fuel|what do rockets burn|rocket petrol|what makes rockets go', a: ['leo', 'Rockets use special fuels, like liquid hydrogen, a type of kerosene, or methane. They also carry their own super cold liquid oxygen to help the fuel burn, because there is no air in space. Some smaller rockets use solid fuel, a bit like a giant firework.'] },

  /* ---------------- Space life ---------------- */
  { id: 'life-aliens', topic: 'Space life', q: 'Are there aliens?', alt: 'aliens|are aliens real|is there life on other planets|do aliens exist|life in space|alians', a: ['leo', 'Nobody knows yet. Scientists have not found any life beyond Earth, but space is so huge, with so many planets, that many think life could be out there somewhere. If we find it, it might be tiny, like germs.'] },
  { id: 'life-look', topic: 'Space life', q: 'What would aliens look like?', alt: 'what do aliens look like|alien shape|green aliens|draw an alien', a: ['leo', 'No one knows, so you can imagine anything. Scientists think the first life we find will probably be tiny, like the smallest germs on Earth. If bigger life exists, it would be suited to its own world, maybe with big eyes for a dim star or fins for an ocean.'] },
  { id: 'life-visited', topic: 'Space life', q: 'Have aliens visited Earth?', alt: 'ufo|ufos|have aliens been to earth|alien spaceship|flying saucer', a: ['leo', 'There is no evidence that aliens have ever visited Earth. Strange lights in the sky usually turn out to be planes, satellites, balloons or planets. Scientists are still searching the sky carefully though, just in case.'] },
  { id: 'life-europa', topic: 'Space life', q: 'Could there be life on Europa?', alt: 'europa|europa ocean|moon with an ocean|europa clipper|life on europa', a: ['leo', 'Europa is an icy moon of Jupiter with a huge salty ocean hidden under its ice. It may have more water than all the oceans of Earth together. Scientists think it is one of the best places to look for life, and a spacecraft called Europa Clipper is on its way there.'] },
  { id: 'life-enceladus', topic: 'Space life', q: 'What is Enceladus?', alt: 'enceladus|ensela|saturn moon with geysers|icy moon|enceladus ocean', a: ['leo', 'Enceladus is a small, sparkly white moon of Saturn. It has a hidden ocean under the ice and shoots fountains of water out into space from its south pole. Scientists think its ocean could be a good home for tiny life.'] },
  { id: 'life-mars', topic: 'Space life', q: 'Is there life on Mars?', alt: 'life on mars|aliens on mars|martians|was there life on mars', a: ['leo', 'We have not found life on Mars. But long ago, Mars had rivers and lakes, so scientists wonder if tiny life could have lived there. The Perseverance rover is collecting rock samples that scientists hope to study for clues.'] },
  { id: 'life-tardigrade', topic: 'Space life', q: 'What is a tardigrade?', alt: 'tardigrade|water bear|tardigrades in space|toughest animal|moss piglet', a: ['leo', 'A tardigrade, or water bear, is a tiny animal about the size of a full stop, with eight chubby legs. They are super tough and once survived being outside a spacecraft in space for ten days. They live in moss and puddles, maybe even near you.'] },
  { id: 'life-goldilocks', topic: 'Space life', q: 'What is the Goldilocks zone?', alt: 'goldilocks zone|habitable zone|planets that could have life|earth like planets', a: ['leo', 'The Goldilocks zone is the area around a star where a planet is not too hot and not too cold, so water could be liquid. Earth is in the Goldilocks zone of the Sun. Scientists hunt for planets in these zones around other stars.'] },
  { id: 'life-signal', topic: 'Space life', q: 'Are scientists listening for aliens?', alt: 'seti|alien signals|messages from aliens|listening for aliens|radio telescope aliens', a: ['leo', 'Yes. Some scientists use giant radio telescopes to listen for signals from faraway civilisations. They have not heard any yet, but space is huge and they have only searched a small part. It is like looking for a fish by checking one glass of seawater.'] },
  { id: 'life-message', topic: 'Space life', q: 'Have we sent messages to aliens?', alt: 'message to aliens|golden record|hello to aliens|send a message into space', a: ['leo', 'Yes. The Voyager spacecraft carry golden records with pictures, music, and hello in 55 languages. Scientists also beamed a radio message into space in 1974. If anyone ever finds them, they will learn a little about life on Earth.'] },
  { id: 'life-plants', topic: 'Space life', q: 'Can plants grow in space?', alt: 'plants in space|growing food in space|space garden|flowers in space|lettuce in space', a: ['leo', 'Yes. Astronauts have grown lettuce, radishes, chilli peppers and even zinnia flowers on the space station. With no up or down, roots and shoots use light and water to find their way. Growing food will be important for long trips to Mars.'] },
  { id: 'life-titan', topic: 'Space life', q: 'Could anything live on Titan?', alt: 'life on titan|titan aliens|methane life|titan lakes', a: ['leo', 'Titan is very cold, and its lakes are full of liquid methane instead of water. Life like ours could not live there. But some scientists wonder whether a very different kind of life might be possible. The Dragonfly mission will help us find out more.'] },

  /* ---------------- Comets and asteroids ---------------- */
  { id: 'comet-what', topic: 'Comets and asteroids', q: 'What is a comet?', alt: 'comet|what are comets|comets made of|commet|dirty snowball', a: ['leo', 'A comet is a lump of ice, dust and rock, a bit like a giant dirty snowball. Most of the time they live far out in the cold. When one comes near the Sun, its ice turns to gas and it grows a glowing head and long tails.'] },
  { id: 'comet-tail', topic: 'Comets and asteroids', q: 'Why do comets have tails?', alt: 'comet tail|why do comets have tails|which way does a comet tail point|comets tail', a: ['leo', 'As a comet gets close to the Sun, the heat turns some of its ice into gas, which carries dust with it. The solar wind and sunlight push this away to make tails millions of kilometres long. The tails always point away from the Sun, even when the comet is leaving.'] },
  { id: 'comet-halley', topic: 'Comets and asteroids', q: 'What is Comet Halley?', alt: 'halleys comet|halley comet|when will halleys comet come back|hailey comet|famous comet', a: ['leo', 'Comet Halley is the most famous comet of all. It comes back near Earth about every 76 years. It was last seen in 1986, and it will return in 2061. You might be able to see it with your own eyes when you are grown up.'] },
  { id: 'asteroid-what', topic: 'Comets and asteroids', q: 'What is an asteroid?', alt: 'asteroid|what are asteroids|asteroids made of|asteroyd|space rock', a: ['leo', 'An asteroid is a rocky or metal space rock that goes around the Sun. They are leftovers from when the planets were made. Some are as small as a car and some are hundreds of kilometres wide. Most are lumpy, like potatoes.'] },
  { id: 'asteroid-belt', topic: 'Comets and asteroids', q: 'What is the asteroid belt?', alt: 'asteroid belt|where are asteroids|belt of asteroids|asteroid field', a: ['leo', 'The asteroid belt is a wide ring of space rocks between Mars and Jupiter. In films it looks crowded, but really the asteroids are very far apart. Spacecraft fly through it easily without bumping into anything.'] },
  { id: 'asteroid-dinosaurs', topic: 'Comets and asteroids', q: 'Did an asteroid kill the dinosaurs?', alt: 'dinosaurs asteroid|what happened to the dinosaurs|why did the dinosaurs die|dinosaur extinction|asteroid dinosaurs', a: ['leo', 'Scientists think a big asteroid about 10 kilometres wide landed in what is now Mexico about 66 million years ago. It changed the weather all over the world, and the big dinosaurs died out. But birds are their relatives, so in a way dinosaurs are still with us.'] },
  { id: 'asteroid-hit-earth', topic: 'Comets and asteroids', q: 'Could an asteroid hit Earth?', alt: 'will an asteroid hit earth|asteroid hitting earth|asteroid danger|asteroid coming|dart mission', a: ['leo', 'Tiny space rocks land on Earth all the time and are harmless. Scientists watch the sky carefully for bigger ones, and none are heading our way. In 2022, a NASA spacecraft called DART even nudged a small asteroid to show we could move one if we ever needed to.'] },
  { id: 'meteorite-what', topic: 'Comets and asteroids', q: 'What is a meteorite?', alt: 'meteorite|meteor or meteorite|difference between meteor and meteorite|meteoroid|space rock on earth', a: ['leo', 'A space rock flying through space is a meteoroid. When it zooms through our air and glows, it is a meteor. If a piece survives and lands on the ground, it is called a meteorite. Some meteorites are older than Earth itself.'] },
  { id: 'meteorite-find', topic: 'Comets and asteroids', q: 'Can I find a meteorite?', alt: 'find a meteorite|how to find a meteorite|touch a meteorite|meteorite in my garden', a: ['leo', 'You might. Meteorites are often darker and heavier than normal rocks, and many stick to a magnet because they contain iron. They are easiest to find in deserts and on ice. Some museums let you touch a real one.'] },
  { id: 'meteor-shower', topic: 'Comets and asteroids', q: 'What is a meteor shower?', alt: 'meteor shower|perseids|lots of shooting stars|when is the next meteor shower|geminids', a: ['leo', 'A meteor shower is when Earth passes through a trail of dust left by a comet, and lots of shooting stars streak across the sky. The Perseids in August and the Geminids in December are two of the best. Lie back somewhere dark and be patient.'] },
  { id: 'crater-what', topic: 'Comets and asteroids', q: 'What is a crater?', alt: 'craters|crater|why does the moon have holes|holes on the moon|impact crater', a: ['leo', 'A crater is a round dent made when a space rock smashes into a planet or moon. The Moon is covered in them because it has no wind or rain to smooth them away. Earth has craters too, but most have worn away or are covered by plants and sea.'] },
  { id: 'comet-oort', topic: 'Comets and asteroids', q: 'Where do comets come from?', alt: 'oort cloud|where do comets live|comet home|edge of the solar system', a: ['leo', 'Many comets come from the Kuiper Belt beyond Neptune, and others from the Oort Cloud, a giant bubble of icy objects even further out. Scientists think the Oort Cloud may stretch more than a quarter of the way to the next star.'] },

  /* ---------------- Big questions ---------------- */
  { id: 'big-bang', topic: 'Big questions', q: 'What was the Big Bang?', alt: 'big bang|how did the universe start|how did space begin|beginning of the universe|big bang theory', a: ['leo', 'Scientists think the universe began about 13.8 billion years ago in the Big Bang. Everything started incredibly hot and tiny, and then space itself began stretching out. Over time, the first stars and galaxies formed. It was not an explosion like a firework, but a giant stretching.'] },
  { id: 'big-before', topic: 'Big questions', q: 'What was before the Big Bang?', alt: 'before the big bang|what happened before the universe|what made the big bang|who made the universe', a: ['leo', 'That is one of the biggest questions anyone can ask, and nobody knows the answer yet. Some scientists think time itself began with the Big Bang. Others have different ideas. It is a great mystery for future scientists, maybe even you.'] },
  { id: 'big-age', topic: 'Big questions', q: 'How old is the universe?', alt: 'age of the universe|how old is space|when did the universe start|universe age', a: ['leo', 'The universe is about 13.8 billion years old. That is about three times older than Earth. If you counted one number every second, it would take you over 400 years just to count to 13.8 billion.'] },
  { id: 'big-size', topic: 'Big questions', q: 'How big is space?', alt: 'how big is the universe|does space go on forever|size of the universe|is space infinite|how big is space', a: ['leo', 'Space is unbelievably big. The part we can see is about 93 billion light years across, and it may go on much further, perhaps forever. Nobody knows for sure. Even light would need billions of years to cross it.'] },
  { id: 'big-edge', topic: 'Big questions', q: 'What is at the edge of the universe?', alt: 'edge of the universe|end of space|does space end|where does space end|what is outside the universe', a: ['leo', 'Scientists think the universe may not have an edge at all. There is a limit to how far we can see, because light from further away has not had time to reach us yet. What lies beyond is a wonderful mystery.'] },
  { id: 'big-light-year', topic: 'Big questions', q: 'What is a light year?', alt: 'light year|light years|how long is a light year|lightyear|light yeer', a: ['leo', 'A light year is not a time, it is a distance. It is how far light travels in one year, about 9.5 trillion kilometres. Space is so huge that we use light years to measure the distances to stars and galaxies.'] },
  { id: 'big-light-speed', topic: 'Big questions', q: 'How fast is light?', alt: 'speed of light|light speed|fastest thing|how fast does light go|can anything go faster than light', a: ['leo', 'Light travels about 300,000 kilometres every second. That is fast enough to go around Earth about seven and a half times in one second. As far as scientists know, nothing can travel faster than light.'] },
  { id: 'big-silent', topic: 'Big questions', q: 'Is space silent?', alt: 'sound in space|is space quiet|can you hear in space|noise in space|can you shout in space', a: ['leo', 'Yes, space is silent. Sound needs something like air to travel through, and space is almost empty. So if you shouted in space, nobody would hear you. Inside the space station there is air, so astronauts can chat happily.'] },
  { id: 'big-dark', topic: 'Big questions', q: 'Why is space dark?', alt: 'why is space black|why is space dark|space colour|why isnt space bright', a: ['leo', 'Space has no air to scatter sunlight around like our blue sky does, so it looks black. Also, the stars are very far apart, and light from the most distant ones has not reached us yet. That is why space is dark between the stars.'] },
  { id: 'big-smell', topic: 'Big questions', q: 'What does space smell like?', alt: 'smell of space|does space smell|space smell|what does space smell of', a: ['leo', 'You cannot smell space directly, but astronauts notice a smell on their suits after a spacewalk. They describe it as like burnt steak, hot metal, or the smell after a firework. Some say it is a bit like a barbecue.'] },
  { id: 'big-cold', topic: 'Big questions', q: 'Is space hot or cold?', alt: 'how cold is space|is space cold|temperature of space|is space freezing', a: ['leo', 'Empty space far from stars is very cold, about minus 270 degrees Celsius. But things in sunlight can get very hot. On the space station, the sunny side gets hotter than boiling water while the shady side is freezing, so it has special insulation.'] },
  { id: 'big-dark-matter', topic: 'Big questions', q: 'What is dark matter?', alt: 'dark matter|dark energy|invisible matter|what is dark energy', a: ['leo', 'Dark matter is invisible stuff that we cannot see, but we can tell it is there because of its gravity. It helps hold galaxies together, like invisible glue. Scientists think there is about five times more dark matter than normal stuff, but they still do not know what it is.'] },
  { id: 'big-made-of', topic: 'Big questions', q: 'What is space made of?', alt: 'what is space|is space empty|space made of|vacuum|what is in space', a: ['leo', 'Space is mostly empty, which is called a vacuum. There are only a few tiny bits of gas floating about, much emptier than anywhere on Earth. Here and there are stars, planets, gas clouds and dust, but they are very far apart.'] },
  { id: 'big-time-travel', topic: 'Big questions', q: 'Is time travel possible?', alt: 'time travel|can we go back in time|time machine|go to the future', a: ['leo', 'In a way, yes. Scientists know that time runs a tiny bit slower when you move very fast. Astronauts on the space station age a few thousandths of a second less than people on Earth over six months. Travelling back in time, though, is still only in stories.'] },
  { id: 'big-alone', topic: 'Big questions', q: 'Why do we explore space?', alt: 'why explore space|why go to space|what is the point of space|why study space|why do we need space', a: ['leo', 'We explore space because people are curious, just like you. Space research has helped invent things like better weather forecasts, sat navs and camera sensors. It also helps us understand where we come from and how special Earth is.'] },
  { id: 'big-universe-what', topic: 'Big questions', q: 'What is the universe?', alt: 'universe|what is the universe|universe meaning|univers|everything in space', a: ['leo', 'The universe is everything there is: all of space, every planet, star and galaxy, and even time itself. Our Earth is a tiny part of the Solar System, which is a tiny part of the Milky Way, which is one of billions of galaxies in the universe.'] },

  /* ---------------- Leo ---------------- */
  { id: 'leo-who', topic: 'Leo', q: 'Who are you?', alt: 'who is leo|what is your name|whats your name|who r u|are you leo|tell me about yourself', a: ['leo', 'I am Leo, your friendly astronaut guide in this space adventure game. I love exploring space and answering questions about planets, stars and rockets. Ask me anything and I will do my best to help.'] },
  { id: 'leo-real', topic: 'Leo', q: 'Are you a real astronaut?', alt: 'are you real|are you a real person|is leo real|are you a robot|are you human', a: ['leo', 'I am a pretend astronaut who lives inside this game, a bit like a character in a storybook. Real astronauts work very hard and train for years. I just love sharing space facts with explorers like you.'] },
  { id: 'leo-age', topic: 'Leo', q: 'How old are you?', alt: 'how old is leo|your age|leo age|how old r u|when is your birthday', a: ['leo', 'I am old enough to fly a rocket and young enough to still love bouncing on the Moon. In Pluto years, I am not even one year old yet. Every day in this game feels like a birthday to me.'] },
  { id: 'leo-dog', topic: 'Leo', q: 'Do you have a dog?', alt: 'do you have a pet|leo dog|have you got a dog|do you have any pets|pet', a: ['leo', 'In my story, I have a fluffy pretend dog called Comet who waits for me at home on Earth. Comet is very good at fetching, but not so good at floating. What pet would you take to space?'] },
  { id: 'leo-fav-planet', topic: 'Leo', q: 'What is your favourite planet?', alt: 'favourite planet|favorite planet|which planet do you like best|best planet|your favourite planet', a: ['leo', 'Earth is my home, so I love it most of all. After that, I have a soft spot for Pluto. It may be small and far away, but it has a giant heart. Saturn and its sparkly rings come a close second.'] },
  { id: 'leo-fav-food', topic: 'Leo', q: 'What is your favourite space food?', alt: 'favourite food|what do you eat|leo food|favorite food|what is your favourite food', a: ['leo', 'My favourite space food is a warm tortilla with cheese, because there are no crumbs to chase around the cabin. For pudding I like dried strawberries. What snack would you take into space?'] },
  { id: 'leo-where-live', topic: 'Leo', q: 'Where do you live?', alt: 'where is your home|where does leo live|your house|where are you|do you live in space', a: ['leo', 'I live in the cosy cabin of our spaceship in this game, with a window looking out at the stars. When we are not exploring, I like to sit there and spot planets. You are always welcome aboard.'] },
  { id: 'leo-been-space', topic: 'Leo', q: 'Have you been to Pluto?', alt: 'have you been to space|have you been to the moon|where have you been|have you visited pluto|have you been to mars', a: ['leo', 'In this game we can fly anywhere together, and Pluto is one of my favourite stops. In real life, no person has been past the Moon yet. The only visitor to Pluto so far is the New Horizons spacecraft.'] },
  { id: 'leo-scared', topic: 'Leo', q: 'Are you ever scared in space?', alt: 'are you scared|do you get scared|is space scary|are you brave|scary', a: ['leo', 'Sometimes new things feel a bit wobbly, and that is okay. Real astronauts practise lots, so they feel calm and ready. When I feel nervous, I take a big slow breath and look out at the beautiful stars.'] },
  { id: 'leo-friend', topic: 'Leo', q: 'Will you be my friend?', alt: 'can we be friends|are you my friend|be my friend|i like you|do you like me|i love you leo', a: ['leo', 'Of course. Every explorer needs a crew mate, and I would love to be yours. Thank you for flying with me. Let us go and discover something amazing together.'] },
  { id: 'leo-colour', topic: 'Leo', q: 'What is your favourite colour?', alt: 'favourite colour|favorite color|what colour do you like|your favourite color', a: ['leo', 'I love the deep blue of Neptune and the soft pink of a sunrise seen from orbit. But the best colour of all might be the shining blue and white of Earth from space. What is your favourite colour?'] },
  { id: 'leo-sleep', topic: 'Leo', q: 'Do you sleep?', alt: 'do you go to bed|when do you sleep|are you tired|leo sleep|goodnight leo', a: ['leo', 'When the game is closed, I zip into my sleeping bag and dream of comets. Rest is important for every explorer, so make sure you get plenty of sleep too. Good night, sleep tight, and see you among the stars.'] },
  { id: 'leo-ship', topic: 'Leo', q: 'What is your spaceship called?', alt: 'spaceship name|what is the rocket called|our ship|your rocket|leo spaceship', a: ['leo', 'Our spaceship is whatever you dream it to be. You can build and fly your own rocket in this game. Every great ship needs a great name, so why not choose one yourself?'] },
  { id: 'leo-joke', topic: 'Leo', q: 'Can you tell me a space joke?', alt: 'tell me a joke|space joke|joke|funny|make me laugh', a: ['leo', 'How do you throw a party in space? You planet. And why did the Sun not go to school? Because it already had a million degrees. I hope that made you smile.'] },
  { id: 'leo-hello', topic: 'Leo', q: 'Hello Leo, how are you?', alt: 'hello|hi|hi leo|how are you|hey|good morning|hiya', a: ['leo', 'Hello, space explorer. It is lovely to see you. What would you like to find out today? You can ask me about planets, stars, rockets, astronauts or anything else in space.'] },,
  { id: 'breathe-in-space', topic: 'Astronauts', q: 'Can you breathe in space?', alt: 'is there air in space|is there oxygen in space|how do astronauts breathe|what happens if you take your helmet off', a: ['leo', 'No, there is no air to breathe in space, so astronauts bring their own. Inside the space station, machines make fresh oxygen, partly from water. Outside, a spacesuit is like a tiny personal spaceship, with its own air supply, heating and cooling.'] }
];
window.LEO_QA_FALLBACK = [
  ['leo', 'Ooh, that is a tricky one! I do not know that yet. Try one of these questions instead.'],
  ['leo', 'Hmm, my space books do not have that one. How about one of these?'],
  ['leo', 'Great question, but I am not sure about that one. Here are some I can answer!']
];
